for i in range(N): G[13][i]=1; G[i][13]=1
# TL template
for r in range(3,5):
 for c in range(3,5): G[r][c]=8
 for c in range(5,7): G[r][c]=7
for r in range(5,7):
 for c in range(1,5): G[r][c]=9
 for c in range(5,7): G[r][c]=2
for r in range(7,9):
 for c in range(5,7): G[r][c]=1
# target anchors
anchors={'TR':(4,19,3),'BL':(21,5,1),'BR':(19,18,4)}
# establish all target 2s
for r,c,n in anchors.values():
 for y in range(r,r+n):
