def put_rect(color, r0,c0,h,w, q):
 rlo,rhi,clo,chi = {'TR':(0,12,14,26),'BL':(14,26,0,12),'BR':(14,26,14,26)}[q]
 for y in range(max(r0,rlo,0), min(r0+h-1,rhi,N-1)+1):
  for x in range(max(c0,clo,0), min(c0+w-1,chi,N-1)+1):
   G[y][x]=color
for q,(r,c,n) in anchors.items():
 if q=='TR':
  put_rect(7,r-n,c,n,n,q)
  put_rect(8,r-n,c+n,n,n,q)
  put_rect(9,r,c+n,n,2*n,q)
  put_rect(1,r+n,c,n,n,q)
 elif q=='BL':
  put_rect(7,r+n,c,n,n,q)
  put_rect(8,r+n,c-n,n,n,q)
  put_rect(9,r,c-2*n,n,2*n,q)
  put_rect(1,r-n,c,n,n,q)
 else:
  put_rect(7,r+n,c,n,n,q)
  put_rect(8,r+n,c+n,n,n,q)
  put_rect(9,r,c+n,n,2*n,q)
  put_rect(1,r-n,c,n,n,q)
